test("entry driver rejects every nested owned alternate constructor mutation", async () => {
	const owned = [
		{ symbol: "lgo_call0", kind: "public", label: "echoRecordAlternate" }
		, { symbol: "borrow", kind: "adapter", label: "identity.borrow" }
		, { symbol: "native", kind: "adapter", label: "echoRecordAlternate:native" }
		, { symbol: "guard", kind: "validator", label: "owned:alternate" }
		, { symbol: "alternate", kind: "constructor", label: "Owned.checkedCountAlternate" }
		, { symbol: "count", kind: "constructor", label: "Owned.checkedCount" }
		, { symbol: "lean", kind: "adapter", label: "echoRecordAlternate:lean" }
		, { symbol: "source", kind: "source", label: "Owned.echoRecordAlternate" }
		, { symbol: "finish", kind: "adapter", label: "transfer.finish" }
	];
	const at = label => owned.find(item => item.label === label);
	const entry = label => ({ kind: at(label).kind, label });
	const nested = ["Owned.checkedCountAlternate", "Owned.checkedCount"];
	const prefix = ["identity.borrow", "echoRecordAlternate:native", "owned:alternate"];
	const shapes = {
		"alternate-valid": [...prefix, ...nested, "echoRecordAlternate:lean"
			, ...nested, "Owned.echoRecordAlternate", "transfer.finish"]
		, "alternate-refusal": [...prefix, ...nested, "transfer.finish"]
	};
	const tally = labels => Object.fromEntries(["validator", "constructor", "adapter", "source"].map(kind => [
		kind, labels.filter(label => at(label).kind === kind).length]));
	const render = labels => "LB_SUBTYPE_ENTRY_V1 begin public echoRecordAlternate\n"
		+ labels.map(label => `LB_SUBTYPE_ENTRY_V1 enter ${at(label).kind} ${label}\n`).join("")
		+ "LB_SUBTYPE_ENTRY_V1 end public echoRecordAlternate\n";
	for(const [control, labels] of Object.entries(shapes))
	{
		const outcome = control === "alternate-valid" ? "accepted" : "refused";
		const ownedCall = { publicName: "echoRecordAlternate"
			, entries: labels.map(entry), counts: tally(labels) };
		const ownedPlan = { scope: "separate-instrumented-probe"
			, family: "owned-subtype", selected: owned
			, cases: [{ control, outcome, call: ownedCall }] };
		const { value } = await driver({ plan: ownedPlan, trace: render(labels) });
		assert.equal(value.entryProbe.counts.constructor, outcome === "accepted" ? 4 : 2);
		const first = labels.indexOf("Owned.checkedCount");
		for(const [name, changed] of [
			["missing", labels.filter((_, index) => index !== first)]
			, ["extra", [...labels.slice(0, first + 1), "Owned.checkedCount", ...labels.slice(first + 1)]]
			, ["reordered", [...labels.slice(0, first - 1), labels[first], labels[first - 1], ...labels.slice(first + 1)]]
			, ["duplicated", [...labels.slice(0, first + 1), ...nested, ...labels.slice(first + 1)]]
		]) await assert.rejects(driver({ plan: ownedPlan, trace: render(changed) }), error => error.message.startsWith(
			`probe entry sequence differs from its independent plan: case 0 (${control}) entry `), `${control} ${name}`);
	}

const bounded = value => {
	const text = String(value);
	return text.length > 120 ? `${text.slice(0, 117)}...` : text;
};
const entryName = entry => entry === undefined ? "none" : bounded(`${entry.kind}:${entry.label}`);
/**
 * Name the first planned/observed divergence with bounded identities and counts only.
 *
 * @param calls - Calls parsed from the probe trace.
 * @param cases - Independently planned cases.
 */
const entryMismatch = (calls, cases) => {
	const totals = `cases expected ${cases.length} observed ${calls.length}`;
	for(let index = 0; index < Math.max(calls.length, cases.length); index++)
	{
		const planned = cases[index]?.call, observed = calls[index];
		if(same(observed, planned)) continue;
		const expectedEntries = planned?.entries ?? [], observedEntries = observed?.entries ?? [];
		let entry = 0;
		while(entry < Math.max(expectedEntries.length, observedEntries.length)
			&& same(expectedEntries[entry], observedEntries[entry])) entry++;
		const where = entry < Math.max(expectedEntries.length, observedEntries.length)
			? `entry ${entry}: expected ${entryName(expectedEntries[entry])} observed ${entryName(observedEntries[entry])}`
			: "entries match, call fields differ";
		return `case ${index} (${bounded(cases[index]?.control ?? "unplanned")}) ${where}; `
			+ `entries expected ${expectedEntries.length} observed ${observedEntries.length}; ${totals}`;
	}
	return totals;
};

import {
	phpWasmOwnedRefinementEntryPlan, phpWasmOwnedSubtypeAlternateConstructors
} from "./php-wasm-owned-refinement-entry-plan.mjs";

test("owned Subtype alternate constructor encloses its authored checkedCount delegation", async () => {
	const lean = await readFile("tests/fixtures/onboarding/owned-subtypes/Owned.lean", "utf8");
	assert.match(lean, /^def checkedCountAlternate \(value : Int\) : Option \{ count : Int \/\/ 0 ≤ count \} :=\n {2}checkedCount value$/mu);
	assert.deepEqual(phpWasmOwnedSubtypeAlternateConstructors, ["checkedCountAlternate", "checkedCount"]);
	assert.ok(Object.isFrozen(phpWasmOwnedSubtypeAlternateConstructors));
	const { plan } = await fixture("owned-subtype");
	const refused = plan.cases.find(value => value.control === "alternate-refusal");
	assert.deepEqual(labels(refused), [
		"identity.borrow", "echoRecordAlternate:native", "owned:refine_alternate"
		, "Owned.checkedCountAlternate", "Owned.checkedCount", "transfer.finish"
	]);
	assert.deepEqual(refused.call.counts, { validator: 1, constructor: 2, adapter: 3, source: 0 });
	const accepted = plan.cases.find(value => value.control === "alternate-valid");
	assert.deepEqual(accepted.call.counts, { validator: 1, constructor: 4, adapter: 4, source: 1 });
	// Only the alternate cases delegate; every other constructor stays a single entry.
	for(const value of plan.cases.filter(item => !item.control.startsWith("alternate-")))
		assert.ok(!labels(value).includes("Owned.checkedCountAlternate"), value.control);
	const entries = refused.call.entries;
	const nested = entries.findIndex(entry => entry.label === "Owned.checkedCount");
	for(const [name, changed] of [
		["missing", entries.filter((_, index) => index !== nested)]
		, ["extra", [...entries.slice(0, nested + 1), entries[nested], ...entries.slice(nested + 1)]]
		, ["reordered", [...entries.slice(0, nested - 1), entries[nested], entries[nested - 1], ...entries.slice(nested + 1)]]
		, ["duplicated", [...entries.slice(0, nested + 1), entries[nested - 1], entries[nested], ...entries.slice(nested + 1)]]
	]) assert.notDeepEqual(changed, entries, name);
});

/**
 * Owned.lean defines checkedCountAlternate as checkedCount, so each alternate
 * constructor entry encloses exactly one checkedCount entry.
 */
export const phpWasmOwnedSubtypeAlternateConstructors
	= Object.freeze(["checkedCountAlternate", "checkedCount"]);

